update_rule.pseudocode:
state.mandate_active = (day >= mandate_start_day)
for each location L in {WorkplaceSchool, PublicPlace}:
  if state.mandate_active:
    L.mask_policy = 'required'
    L.enforcement_level = min(1.0, L.enforcement_level * mandate_strictness * enforcement_strength)
  else:
    L.mask_policy = 'recommended'
compute policy_pressure_by_person[i] = (state.mandate_active ? policy_weight * (mandate_strictness) : 0) * (location_visits_i)
run media campaign if state.mandate_active or campaign_intensity>0:
  for each MediaChannel m:
    effective_reach = m.reach * campaign_intensity * authority_credibility
    for audience within reach:
      increase risk_perception by delta = 0.02 * authority_credibility * campaign_intensity * m.message_frequency * sign(message_valence)
allocate enforcement resources across locations proportional to occupancy and enforcement_level
